?><!doctype html><html lang="no"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Hotellet vårt</title><style>.hotel-art{display:block;width:100%;border-radius:24px;box-shadow:0 15px 45px #66483122}body{margin:0;min-height:100dvh;display:grid;place-items:center;background:#fcf1df;color:#3e3852;font:18px system-ui}main{max-width:380px;margin:24px;text-align:center}h1{font-size:38px}button{font:inherit;background:#7259a1;color:white;border:0;border-radius:24px;padding:15px 25px;cursor:pointer}.hotel{font-size:90px}p{line-height:1.6}small{display:block;margin-top:30px}</style><main><img class="hotel-art" src="/hotell-kort.jpg" alt="Et rosa hotell med seks rom og blomsterhage"><h1>Hotellet vårt</h1><p id="message">Dette hotellet er privat. Åpne din personlige invitasjon for å flytte inn.</p><button id="activate" hidden>Åpne mitt hotell</button><small>Har du byttet telefon eller nettleser?<br>Be Remi om en ny invitasjon.</small></main><script>const p=new URLSearchParams(location.hash.slice(1));const t=p.get('invite');history.replaceState(null,'',location.pathname);if(t){document.querySelector('#message').textContent='Invitasjonen knytter denne nettleseren til din plass. Bruk din egen telefon.';const b=document.querySelector('#activate');b.hidden=false;b.onclick=async()=>{b.disabled=true;try{const r=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'activate',token:t})});const j=await r.json();if(!j.ok)throw Error(j.error);location.reload();}catch(e){document.querySelector('#message').textContent=e.message;b.disabled=false;}}}</script></html>
